def sq_window(grid):
    n=min(len(grid),len(grid[0]))
    best=[]
    for i in range(len(grid)-n+1):
        for j in range(len(grid[0])-n+1):
            w=[row[j:j+n] for row in grid[i:i+n]]
            s=sum(sum(r) for r in w); d=len(set(x for r in w for x in r))
            best.append((s,d,i,j,w))
    return best
