import os,re,json,math
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
pos={1:(15,0),2:(0,12),3:(7,0),4:(6,0),5:(0,4),6:(12,0),7:(0,15),8:(10,0)}
feats={
 'S':lambda b,n:sum(sum(r) for r in b),
 'Sno0':lambda b,n:sum(x for r in b for x in r if x!=0),
 'MD':lambda b,n:max(set(x for r in b for x in r)),
 'MNZ':lambda b,n:min(x for r in b for x in r if x!=0),
 'ODDSUM':lambda b,n:sum(x for r in b for x in r if x%2==1),
 'PROD':lambda b,n:abs(math.prod(x for r in b for x in r)),
 'MODEMAX':lambda b,n:Counter(x for r in b for x in r).most_common(1)[0][0],
}
tot={}
for pn,fn in feats.items():
    ok=[]
    for n in range(1,9):
        gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
        h,w=len(gi),len(gi[0]); N=len(go)
        vals={}
        for i_ in range(h-N+1):
            for j_ in range(w-N+1):
                b=[row[j_:j_+N] for row in gi[i_:i_+N]]
                vals[(i_,j_)]=fn(b,N)
        hh=pos[n]; hv=vals[hh]
        mnv,mxv=min(vals.values()),max(vals.values())
        tiesm=sum(1 for v in vals.values() if v==mnv); tiesmx=sum(1 for v in vals.values() if v==mxv)
        uniqmin=(hv==mnv and tiesm==1); uniqmax=(hv==mxv and tiesmx==1)
        ok.append('UNQ-' + ('MIN' if uniqmin else '') + ('MAX' if uniqmax else ''))
    tot[pn]=ok
print('features per demo (UNQ-MIN/MAX / none):')
for pn,ok in tot.items(): print(pn,ok)
